import {useCases,useCaseCategories} from './usecases-data.js';
// Product explanation: all prose is read from the active database-backed locale.
export function createProductStory({s,t,h,icon,url,link,badge,campaignFrame,getSlide,isPaused}) {
  let mode='space',role='architect',customer='architect',problem='apartment-plan';
  const openQuestions=new Set();
  const modes=['object','measure','space'];
  const paths={object:'/objects',measure:'/measure',space:'/spaces'};
  const icons={object:'cube',measure:'ruler',space:'room'};
  const scene={object:'06-architect',measure:'07-mario-walls',space:'08-design-couple'};
  const alt={object:'campaign.slide1Alt',measure:'campaign.slide3Alt',space:'spaces.designAlt'};
  const people={architect:['06-architect','campaign.slide1Alt'],designer:['08-design-couple','spaces.designAlt'],builder:['09-repair-foreman','spaces.repairAlt'],maker:['06-architect','campaign.slide1Alt'],property:['08-design-couple','spaces.designAlt'],creator:['02-face','campaign.slide2Alt']};

  const customerOrder=['architect','designer','builder','maker','property','creator'];
  const categoryProfiles={architect:['spaces_property','repair_construction','measure_diy'],designer:['interior_design','objects_print','measure_diy'],builder:['repair_construction','measure_diy'],maker:['objects_print'],property:['spaces_property','measure_diy','repair_construction'],creator:['people_creative','objects_print'],all:useCaseCategories};
  const defaultProblems={architect:'apartment-plan',designer:'room-redesign',builder:'repair-list',maker:'print-replica',property:'property-presentation',creator:'portrait-keepsake',all:'furniture-fit'};
  const caseMode=item=>item.module==='/measure'?'measure':item.module==='/spaces'?'space':'object';
  const currentCase=()=>useCases.find(item=>item.id===problem);
  const rolePath=()=>role==='maker'?'/objects':role==='creator'?'/people':'/spaces';
  const sample=()=>role==='maker'?['cube-100mm.stl','docs.sampleCube','docs.sampleText']:role==='creator'?['reference-cloud.ply','docs.sampleCloud','docs.sampleText']:['room-4x3m.dxf','v2.sampleDownload','v2.sampleNote'];
  function problemOptions(){return categoryProfiles[customer].map(category=>'<optgroup label="'+s('uses.category.'+category)+'">'+useCases.filter(item=>item.category===category).map(item=>'<option value="'+item.id+'" '+(problem===item.id?'selected':'')+'>'+s('usecase.'+item.id+'.title')+'</option>').join('')+'</optgroup>').join('');}
  function customerSelectors(){return '<div class="customer-finder"><label for="customer-profile"><span>01</span>'+s('v2.customerLabel')+'</label><select id="customer-profile">'+[...customerOrder,'all'].map(id=>'<option value="'+id+'" '+(customer===id?'selected':'')+'>'+s(id==='all'?'v2.anyProfile':'v2.'+id)+'</option>').join('')+'</select><label for="customer-problem"><span>02</span>'+s('v2.problemLabel')+'</label><select id="customer-problem">'+problemOptions()+'</select></div>';}
  function customerAnswer(){const item=currentCase();return '<span class="eyebrow">'+s('v2.result')+'</span><h2>'+s('usecase.'+item.id+'.title')+'</h2><p>'+s('usecase.'+item.id+'.description')+'</p>'+link(item.module,'v2.detail','text-link');}
  function modeControls(){return '<div class="mode-selector" role="group" aria-label="'+s('v2.choose')+'">'+modes.map(m=>'<button data-demo="'+m+'" aria-pressed="'+(mode===m)+'">'+icon(icons[m])+s('v2.'+m)+'</button>').join('')+'</div>';}
  function refreshCustomer({updateOptions=false}={}){
    const item=currentCase();mode=caseMode(item);
    const stageElement=document.getElementById('product-demo');
    if(!stageElement)return;
    if(updateOptions)document.getElementById('customer-problem').innerHTML=problemOptions();
    stageElement.dataset.mode=mode;stageElement.innerHTML=stage();
    document.getElementById('customer-answer').innerHTML=customerAnswer();
    document.getElementById('demo-outcomes').innerHTML=outcomes();
    document.getElementById('role-panel').innerHTML=rolePanel();
    document.querySelectorAll('[data-demo]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.demo===mode)));
    document.querySelectorAll('[data-profession]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.profession===role)));
  }
  document.addEventListener('change',event=>{
    if(event.target.id==='customer-profile'&&Object.hasOwn(categoryProfiles,event.target.value)){
      customer=event.target.value;role=customer==='all'?'designer':customer;problem=defaultProblems[customer];refreshCustomer({updateOptions:true});
    }
    if(event.target.id==='customer-problem'&&useCases.some(item=>item.id===event.target.value&&categoryProfiles[customer].includes(item.category))){
      problem=event.target.value;
      if(customer==='all')role=({objects_print:'maker',measure_diy:'builder',interior_design:'designer',repair_construction:'builder',spaces_property:'property',people_creative:'creator'})[currentCase().category];
      refreshCustomer();
    }
  });
  const portraitDrawing=()=>'<svg viewBox="0 0 300 330" aria-hidden="true"><g fill="none" stroke="#79efdc" stroke-width="1.4"><ellipse cx="150" cy="128" rx="62" ry="84"/><path d="M91 105h118M89 140h122M102 174h96M118 52l-8 140m39-149v169m31-160 11 140M90 114l120 38M90 152l121-38M70 296v-40q14-36 58-45m44 0q44 9 58 45v40M70 256h160M90 230l120 64m0-64L90 294"/></g><text x="150" y="322" text-anchor="middle" fill="#c6d5ed" font-size="12">3D</text></svg>';
  const drawing=()=>mode==='object'&&currentCase().module==='/people'?portraitDrawing():mode==='object'?`<svg viewBox="0 0 300 330" aria-hidden="true"><g class="wire-object"><path d="m150 60 95 54v110l-95 54-95-54V114Z"/><path d="m55 114 95 55 95-55M150 169v109M150 60v109"/><path class="wire-back" d="m55 224 95-55 95 55"/><path class="dim-line" d="M37 114H20v110h17M55 246v47h95M245 245v48h-95"/></g><g class="svg-label"><text x="150" y="317" text-anchor="middle">100 mm</text><text x="15" y="172" transform="rotate(-90 15 172)" text-anchor="middle">100 mm</text></g></svg>`:mode==='measure'?`<svg viewBox="0 0 300 330" aria-hidden="true"><path class="wall-plane" d="m32 88 236-20v185L32 272Z"/><path class="wall-opening" d="m175 146 59-4v114l-59 5Z"/><path class="dim-line" d="M32 63V41m236 0v-24M32 45l236-21M32 45l6 4m262-26-5 7"/><circle class="point" cx="32" cy="88" r="6"/><circle class="point" cx="268" cy="68" r="6"/><g class="svg-label"><text x="140" y="25" text-anchor="middle">4.00 m</text><text x="144" y="310" text-anchor="middle">4.00 × 2.80 m</text></g></svg>`:`<svg viewBox="0 0 300 330" aria-hidden="true"><path class="plan-fill" d="M30 70h240v205H30z"/><path class="plan-wall" d="M30 70h240v205H30V70Zm145 0v80m0 40v85M30 184h65m34 0h46m0-34h95"/><path class="plan-door" d="M95 184v-34q34 0 34 34m46-34h40q0 40-40 40"/><rect class="furniture" x="48" y="90" width="63" height="28" rx="3"/><rect class="furniture" x="206" y="85" width="42" height="49" rx="3"/><path class="dim-line" d="M30 48V30m240 18V30M30 37h240M281 70h15m-15 205h15M289 70v205"/><g class="svg-label"><text x="150" y="26" text-anchor="middle">8.00 m</text><text x="150" y="311" text-anchor="middle">3 ${s('nav.spaces').toLowerCase()}</text></g></svg>`;
  function stage(){return `<div class="stage-context"><img src="/assets/campaign/${currentCase().module==='/people'&&mode==='object'?'02-face':scene[mode]}.webp" width="1536" height="1024" alt="${s(currentCase().module==='/people'&&mode==='object'?'campaign.slide2Alt':alt[mode])}" fetchpriority="high"><span>${s('status.concept')}</span></div><div class="phone-shell"><div class="phone-camera" aria-hidden="true"></div><div class="phone-top"><img src="/assets/eva-app-icon.svg" width="25" height="25" alt=""><strong>EVA-3dScan</strong>${icon('focus')}</div><div class="phone-title">${currentCase().module==='/people'&&mode==='object'?'3D':s('v2.'+(mode==='object'?'dimension':mode==='measure'?'wall':'connected'))}</div><div class="phone-viewport">${drawing()}<div class="phone-scanline" aria-hidden="true"></div></div><div class="phone-result"><span>${s('v2.preview')}</span><strong>${mode==='object'?(currentCase().module==='/people'?'3D':'100 × 100 × 100 mm'):mode==='measure'?'4.00 m':'3D → 2D'}</strong></div><div class="phone-bottom"><span class="capture-dot" aria-hidden="true"></span><span>${s('v2.demoLabel')}</span></div></div><div class="stage-chip">${icon(icons[mode])}<div><small>0${modes.indexOf(mode)+1} / 03</small><strong>${s(currentCase().module==='/people'&&mode==='object'?'usecase.'+problem+'.title':'v2.'+mode+'Result')}</strong></div></div>`;}
  function outcomes(){if(currentCase().module==='/people'&&mode==='object')return '<div><span class="outcome-index">01</span><span><small>'+s('v2.capture')+'</small><strong>'+s('people.title')+'</strong></span></div><div><span class="outcome-index">02</span><span><small>'+s('v2.result')+'</small><strong>'+s('usecase.'+problem+'.title')+'</strong></span></div><div><span class="outcome-index">03</span><span><small>'+s('v2.use')+'</small><strong>'+s('usecase.'+problem+'.description')+'</strong></span></div>';return [['capture','Input'],['result','Result'],['use','Use']].map(([label,suffix],i)=>`<div><span class="outcome-index">0${i+1}</span><span><small>${s('v2.'+label)}</small><strong>${s('v2.'+mode+suffix)}</strong></span>${i<2?'<b aria-hidden="true">→</b>':''}</div>`).join('');}
  function roleProof(){if(role==='maker'||role==='creator')return '<div class="role-proof"><div><small>'+s('v2.demoLabel')+'</small><strong>'+s('v2.preview')+'</strong></div><svg viewBox="0 0 260 110" role="img" aria-label="'+s('v2.demoLabel')+': '+(role==='maker'?'100 × 100 × 100 mm':'3D')+'">'+(role==='maker'?'<path class="proof-wall" d="m125 10 50 23v49l-50 23-50-23V33Z M75 33l50 24 50-24M125 57v48"/><text x="210" y="62" text-anchor="middle">100 mm</text>':'<g fill="none" stroke="#2549eb"><ellipse cx="130" cy="45" rx="25" ry="33"/><path d="M105 32h50m-50 20h50m-45 13h40m-20-53v66M90 105V89l24-13m32 0 24 13v16M114 18l-5 47m37-47 5 47"/></g><text x="205" y="60">3D</text>')+'</svg></div>';return `<div class="role-proof"><div><small>${s('v2.demoLabel')}</small><strong>${s('v2.'+(role==='builder'?'wall':role==='designer'?'dimension':'connected'))}</strong></div><svg viewBox="0 0 260 110" role="img" aria-label="${s('v2.demoLabel')}: ${s('v2.dimension')} ${role==='builder'?'4.00 m':role==='designer'?'2.00 m / 0.85 m':'4.00 m / 3.00 m'}">${role==='builder'?'<path class="proof-wall" d="M20 30h220v65H20zM165 95V52h45v43"/><path class="proof-damage" d="m65 40 8 12-9 8 12 13-6 12"/><path class="dim-line" d="M20 15h220m-220-5v10m220-10v10"/><text x="130" y="11" text-anchor="middle">4.00 m</text>':role==='designer'?'<path class="proof-wall" d="M20 25h220v70H20z"/><rect class="proof-furniture" x="35" y="40" width="95" height="37" rx="4"/><path class="dim-line" d="M138 57h77m-77-5v10m77-10v10M35 14h95"/><text x="176" y="49" text-anchor="middle">0.85 m</text><text x="82" y="11" text-anchor="middle">2.00 m</text>':'<path class="proof-wall" d="M20 25h220v70H20zM140 25v27m0 23v20"/><path class="proof-door" d="M140 52h23q0 23-23 23"/><path class="dim-line" d="M20 14h120m-120-4v8m120-8v8M153 14h87"/><text x="80" y="10" text-anchor="middle">4.00 m</text><text x="196" y="10" text-anchor="middle">3.00 m</text>'}</svg></div>`;}
  function rolePanel(){const [file,a]=people[role];return `<figure class="role-scene"><img src="/assets/campaign/${file}.webp" width="1536" height="1024" alt="${s(a)}" loading="lazy"><figcaption>${s('status.concept')}</figcaption>${roleProof()}</figure><div class="role-copy"><span class="eyebrow">${s('v2.'+role)}</span><h3>${s('v2.'+role+'Title')}</h3><p>${s('v2.'+role+'Need')}</p><ol>${t('v2.'+role+'Steps').split('|').map(step=>`<li>${h(step)}</li>`).join('')}</ol><div class="role-deliverable"><span>${icon('check')}${s('v2.deliverable')}</span><p>${s('v2.'+role+'Deliverable')}</p></div><a class="text-link" href="/downloads/${sample()[0]}" download>${s(sample()[1])} ${icon('download')}</a><small class="sample-disclosure">${s(sample()[2])}</small><div class="role-module-link">${link(rolePath(),'v2.detail','text-link')}</div></div>`;}
  function home(){return `<section class="product-hero container"><div class="product-pitch"><div class="product-label"><img src="/assets/eva-app-icon.svg" width="42" height="42" alt=""><span>EVA-3dScan <b>iPhone APP</b></span></div><div class="eyebrow">${s('v2.customerKicker')}</div><h1>${s('hero.title')}</h1><p class="product-intro">${s('campaign.heroIntro')}</p>${customerSelectors()}<div class="button-row"><a class="button primary" href="#customer-answer">${s('v2.detail')} <span aria-hidden="true">↗</span></a>${link('/uses','v2.nextCta','button story-secondary')}</div><div class="product-status">${badge()}<span>${s('v2.heroAccent')}</span></div></div><div class="product-stage" id="product-demo" data-mode="${mode}" role="region" aria-label="${s('v2.preview')}">${stage()}</div></section><section class="container customer-result"><div id="customer-answer" aria-live="polite">${customerAnswer()}</div><div class="customer-demo-choice"><span class="eyebrow">${s('v2.choose')}</span>${modeControls()}<p>${s('v2.sampleOnly')}</p></div></section><section class="container result-section"><div class="demo-outcomes" id="demo-outcomes" aria-live="polite">${outcomes()}</div><p class="demo-disclosure">${s('v2.sampleOnly')}</p></section><section class="professional-section" id="your-work"><div class="container"><div class="section-heading"><div><span class="eyebrow">01 / ${s('v2.rolesEyebrow')}</span><h2>${s('v2.clientsTitle')}</h2></div><p>${s('v2.clientsIntro')}</p></div><div class="role-selector" role="group" aria-label="${s('v2.clientsTitle')}">${customerOrder.map(r=>`<button data-profession="${r}" aria-pressed="${role===r}"><small>${s('v2.'+r)}</small><strong>${s('v2.activity.'+r)}</strong><span aria-hidden="true">↗</span></button>`).join('')}</div><div class="role-panel" id="role-panel" aria-live="polite">${rolePanel()}</div></div></section><section class="product-modules container" id="modules"><div class="section-heading"><div><span class="eyebrow">02 / EVA-3dScan</span><h2>${s('v2.modulesTitle')}</h2></div><p>${s('v2.modulesIntro')}</p></div><div class="clear-modules">${modes.map((m,i)=>`<a class="clear-module product-module module-${i+1}" href="${url(paths[m])}" data-route="${paths[m]}"><div class="clear-module-top"><span>0${i+1}</span>${icon(icons[m])}</div><h3>${s('v2.'+m+'Detail')}</h3><p>${s('v2.'+m+'Result')}</p><div class="module-output"><span>${s('v2.detail')}</span><b aria-hidden="true">↗</b></div></a>`).join('')}</div></section><section class="inspiration-section container"><div class="inspiration-copy"><span class="eyebrow">03 / ${s('uses.homeLabel')}</span><h2>${s('v2.inspirationTitle')}</h2><p>${s('v2.inspirationText')}</p>${link('/uses','v2.nextCta','button primary')}<div class="portrait-link"><img src="/assets/campaign/02-face.webp" width="100" height="68" alt="${s('campaign.slide2Alt')}" loading="lazy">${link('/people','people.homeLink','text-link')}</div></div><div class="campaign-carousel" id="campaign-carousel" role="region" aria-roledescription="carousel" aria-label="${s('campaign.carouselLabel')}" tabindex="0">${campaignFrame()}<div class="carousel-bottom"><div class="carousel-dots">${[0,1,2,3,4].map(i=>`<button data-slide="${i}" aria-label="${s('campaign.slideLabel')} ${i+1}" aria-pressed="${i===getSlide()}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div class="carousel-controls"><button id="carousel-prev" aria-label="${s('campaign.previous')}">←</button><button id="carousel-toggle" aria-label="${s(isPaused()?'campaign.play':'campaign.pause')}">${isPaused()?'▶':'Ⅱ'}</button><button id="carousel-next" aria-label="${s('campaign.next')}">→</button></div></div><div class="campaign-note">${s('campaign.campaignNote')}</div></div></section><section class="questions-section container"><div><span class="eyebrow">04 / EVA-3dScan</span><h2>${s('v2.questionsTitle')}</h2>${link('/technology','nav.technology','text-link')}</div><div class="questions-list">${[1,2,3,4].map(i=>`<details data-question="${i}" ${openQuestions.has(i)?'open':''}><summary data-faq="${i}">${s('v2.faq'+i+'Title')}<span aria-hidden="true">+</span></summary><p>${s('v2.faq'+i+'Text')}</p></details>`).join('')}</div></section><section class="next-section container"><div><h2>${s('v2.nextTitle')}</h2><p>${s('v2.nextText')}</p></div>${link('/uses','v2.nextCta','button primary')}</section>`;}
  document.addEventListener('click',event=>{
    const demo=event.target.closest('[data-demo]');
    if(demo&&modes.includes(demo.dataset.demo)){
      mode=demo.dataset.demo;problem=({object:'scan-object',measure:'wall-size',space:'apartment-plan'})[mode];
      if(!categoryProfiles[customer].includes(currentCase().category))customer='all';
      if(customer==='all')role=({object:'maker',measure:'builder',space:'property'})[mode];
      const profile=document.getElementById('customer-profile');if(profile)profile.value=customer;
      refreshCustomer({updateOptions:true});
    }
    const profession=event.target.closest('[data-profession]');
    if(profession&&Object.hasOwn(people,profession.dataset.profession)){
      role=profession.dataset.profession;customer=role;problem=defaultProblems[role];
      const profile=document.getElementById('customer-profile');if(profile)profile.value=customer;
      refreshCustomer({updateOptions:true});
    }
  });
  document.addEventListener('toggle',event=>{
    if(event.target.matches?.('details[data-question]')){
      const id=Number(event.target.dataset.question);
      if(event.target.open)openQuestions.add(id);else openQuestions.delete(id);
    }
  },true);
  return {home};
}
